var SAATLER=SAATLER_JSON;
var gunler=['Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi'];
var bugun=new Date().getDay();
var bugunAdi=gunler[bugun];
function saatKontrol(){
  var s=SAATLER.find(function(x){return x.gun===bugunAdi;});
  var badge=document.getElementById('acik-kapali');
  if(!s||!s.acilis){badge.innerHTML='<span style="background:#c62828;color:#fff;padding:6px 16px;border-radius:20px;font-size:0.85rem;font-weight:700">🔴 Bugün Kapalı</span>';return;}
  var simdi=new Date();
  var saat=String(simdi.getHours()).padStart(2,'0')+':'+String(simdi.getMinutes()).padStart(2,'0');
  var acik=saat>=s.acilis&&saat<=s.kapanis;
  badge.innerHTML=acik?'<span style="background:#2e7d32;color:#fff;padding:6px 16px;border-radius:20px;font-size:0.85rem;font-weight:700">🟢 Şu An Açık — '+s.kapanis+"'e kadar</span>":'<span style="background:#c62828;color:#fff;padding:6px 16px;border-radius:20px;font-size:0.85rem;font-weight:700">🔴 Şu An Kapalı</span>';
}
